import gurobipy as gp
from gurobipy import GRB
capacity = None
for rec in LEGACY_RECORDS:
    if rec['source'].endswith('capacity.csv'):
        vals = rec['values']
        if 'Capacity' in vals:
            capacity = int(vals['Capacity'])
if capacity is None:
    raise ValueError('Missing total development capacity in LEGACY_RECORDS.')
areas = []
value = {}
weight = {}
for rec in LEGACY_RECORDS:
    if rec['source'].endswith('products.csv'):
        vals = rec['values']
        area = vals['ProductName']
        areas.append(area)
        try:
            value[area] = int(vals['Value'])
            weight[area] = int(vals['Weight'])
        except Exception as e:
            raise ValueError(f'Invalid Value or Weight for area {area}: {e}')
if len(set(areas)) != len(areas):
    raise ValueError('Duplicate area names found in LEGACY_RECORDS.')
if set(value.keys()) != set(areas) or set(weight.keys()) != set(areas):
    raise ValueError('Mismatch in area keys for value/weight.')
m = gp.Model('NYC_Development')
x_vars = m.addVars(areas, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((value[a] * x_vars[a] for a in areas)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((weight[a] * x_vars[a] for a in areas)) <= capacity, name='capacity')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')